"""Simple weekly shift scheduler for a small restaurant (draft)."""
from collections import defaultdict

DAYS = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"]

def build_schedule(staff, shifts_needed):
    """staff: {name: max_shifts_per_week}; shifts_needed: {day: count}.
    Returns {day: [names]} filling each day round-robin by fewest shifts so far."""
    load = defaultdict(int)
    plan = {d: [] for d in DAYS}
    for day in DAYS:
        for _ in range(shifts_needed.get(day, 0)):
            candidates = [n for n in staff if load[n] < staff[n] and n not in plan[day]]
            if not candidates:
                plan[day].append("UNFILLED")
                continue
            pick = min(candidates, key=lambda n: load[n])
            plan[day].append(pick)
            load[pick] += 1
    return plan

if __name__ == "__main__":
    staff = {"Ana": 5, "Ben": 4, "Chris": 3}
    needed = {"Mon": 2, "Tue": 2, "Wed": 2, "Thu": 3, "Fri": 3, "Sat": 3, "Sun": 2}
    for day, names in build_schedule(staff, needed).items():
        print(day, ", ".join(names))
EOF
